<template>
  <q-page class="dashboard-page q-pa-md"><div class="dashboard-wrap">
    <header class="dashboard-header"><div><div class="eyebrow"><q-icon name="auto_awesome"/> Panel principal</div><h1>{{ empresa.nombreComercial || 'Mi supermercado' }}</h1><p>Resumen de actividad y rendimiento del negocio.</p></div><div class="header-actions"><span>{{ fechaActual }}</span><q-btn unelevated no-caps color="green-8" icon="point_of_sale" label="Nueva venta" to="/ventas"/></div></header>
    <q-banner v-if="error" rounded class="error-banner q-mb-lg"><template #avatar><q-icon name="info"/></template>{{ error }}</q-banner>
    <section class="kpi-grid"><q-card v-for="card in kpis" :key="card.label" flat bordered class="kpi-card"><q-card-section><div class="kpi-top"><div class="kpi-icon" :class="card.tone"><q-icon :name="card.icon"/></div><q-icon name="trending_up" class="trend"/></div><div class="label">{{ card.label }}</div><div class="value">{{ card.value }}</div><small>{{ card.help }}</small></q-card-section></q-card></section>
    <section class="content-grid q-mt-lg"><q-card flat bordered class="panel"><q-card-section class="panel-title"><div><h2>Ventas recientes</h2><small>Últimas operaciones registradas</small></div><q-icon name="show_chart"/></q-card-section><q-card-section class="bars"><div v-for="bar in barrasVentas" :key="bar.label" class="bar-col"><span>Bs {{ bar.value.toFixed(0) }}</span><div class="bar" :style="{height:bar.height+'%'}"/><small>{{ bar.label }}</small></div></q-card-section></q-card><q-card flat bordered class="panel"><q-card-section class="panel-title"><div><h2>Métodos de pago</h2><small>Distribución de ventas</small></div><q-icon name="pie_chart"/></q-card-section><q-card-section><div v-for="item in pagos" :key="item.label" class="pay-row"><span><i :class="item.tone"/>{{ item.label }}</span><strong>Bs {{ item.value.toFixed(2) }}</strong></div><div v-if="!pagos.length" class="empty">No hay ventas registradas.</div></q-card-section></q-card></section>
    <section class="content-grid q-mt-lg"><q-card flat bordered class="panel"><q-card-section class="panel-title"><div><h2>Alertas de inventario</h2><small>Estado actual de existencias</small></div><q-icon name="inventory_2"/></q-card-section><q-card-section><div class="alert-row"><q-icon name="remove_shopping_cart" class="red"/><span><strong>{{ inventario.sin || 0 }} productos agotados</strong><small>Requieren reposición inmediata</small></span></div><div class="alert-row"><q-icon name="trending_down" class="amber"/><span><strong>{{ inventario.bajo || 0 }} productos con stock bajo</strong><small>Revisa los niveles mínimos</small></span></div><div class="alert-row"><q-icon name="event_busy" class="orange"/><span><strong>{{ inventario.vencen || 0 }} próximos a vencer</strong><small>Dentro de 30 días</small></span></div></q-card-section></q-card><q-card flat bordered class="panel"><q-card-section class="panel-title"><div><h2>Últimas ventas</h2><small>Actividad más reciente</small></div><q-btn flat dense no-caps color="green-8" label="Ver todas" to="/historial-ventas"/></q-card-section><q-list separator><q-item v-for="venta in ultimasVentas" :key="venta.idVenta || venta.codigo"><q-item-section avatar><q-avatar color="green-1" text-color="green-9" icon="receipt_long"/></q-item-section><q-item-section><q-item-label class="sale-code">{{ venta.codigo || 'Venta' }}</q-item-label><q-item-label caption>{{ venta.cliente || 'Consumidor final' }} · {{ fechaVenta(venta.fechaVenta) }}</q-item-label></q-item-section><q-item-section side class="sale-total">Bs {{ Number(venta.total || 0).toFixed(2) }}</q-item-section></q-item><div v-if="!ultimasVentas.length" class="empty">Aún no hay ventas registradas.</div></q-list></q-card></section>
    <section class="quick-actions q-mt-lg"><q-btn v-for="a in acciones" :key="a.label" flat class="quick" :to="a.to"><q-icon :name="a.icon"/> {{ a.label }}</q-btn></section>
  </div></q-page>
</template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { obtenerDashboardVentas, obtenerResumenVentas, listarVentas } from '../../api/venta/venta'
import { getProductoDashboard } from '../../api/productos/productos'
import { obtenerResumen } from '../../api/inventario/inventario'
import { obtenerConfiguracionEmpresa } from '../../api/configuracion/configuracionEmpresa'
const error=ref(''),ventas=ref([]),empresa=reactive({nombreComercial:''}),resumen=reactive({totalVentas:0,totalVendido:0,pendientesCobro:0,gananciaDiaria:0}),productos=reactive({total:0}),inventario=reactive({stock:0,bajo:0,sin:0,vencen:0}),dashboardVentas=reactive({ventasPorDia:[],ventasPorMetodoPago:[]})
const fechaActual=new Date().toLocaleDateString('es-BO',{weekday:'long',day:'numeric',month:'long',year:'numeric'}),money=v=>`Bs ${Number(v||0).toFixed(2)}`
const kpis=computed(()=>[{label:'Ventas acumuladas',value:money(resumen.totalVendido),help:`${resumen.totalVentas||0} ventas registradas`,icon:'payments',tone:'green'},{label:'Ganancia del día',value:money(resumen.gananciaDiaria),help:'Resultado calculado hoy',icon:'trending_up',tone:'blue'},{label:'Pendientes de cobro',value:String(resumen.pendientesCobro||0),help:'Ventas a crédito',icon:'credit_score',tone:'orange'},{label:'Productos activos',value:String(productos.total||0),help:`${inventario.stock||0} con existencia`,icon:'inventory_2',tone:'purple'}])
const ultimasVentas = computed(() => ventas.value.slice(0, 5))
const barrasVentas = computed(() => {
  const dias = dashboardVentas.ventasPorDia || []
  const maximo = Math.max(...dias.map(item => Number(item.total || 0)), 1)
  return dias.map(item => ({ fecha: item.fecha, value: Number(item.total || 0), height: Math.max(Number(item.total || 0) / maximo * 100, Number(item.total || 0) ? 8 : 2), label: item.etiqueta }))
})
const pagos = computed(() => (dashboardVentas.ventasPorMetodoPago || []).map((item, indice) => ({ label: formatearMetodo(item.metodo), value: Number(item.total || 0), tone: ['green', 'blue', 'orange', 'purple'][indice % 4] })))
const acciones = [{label:'Nueva venta',icon:'point_of_sale',to:'/ventas'},{label:'Inventario',icon:'inventory_2',to:'/inventario'},{label:'Clientes',icon:'people',to:'/clientes'},{label:'Caja',icon:'account_balance_wallet',to:'/caja'}]
function fechaVenta(v){return v?new Date(v).toLocaleString('es-BO',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'--'}
function formatearMetodo(m){return {EFECTIVO:'Efectivo',QR:'QR',MIXTO:'Mixto',CREDITO:'Crédito'}[m]||m||'Otros'}
async function cargar(){try{const[v,r,p,i,e,d]=await Promise.all([listarVentas({page:0,size:20,sortBy:'fechaVenta',sortDir:'desc'}),obtenerResumenVentas(),getProductoDashboard(),obtenerResumen(),obtenerConfiguracionEmpresa(),obtenerDashboardVentas()]);ventas.value=v?.content||[];Object.assign(resumen,r||{});Object.assign(productos,{total:p?.total ?? p?.activos ?? 0});Object.assign(inventario,{stock:i?.productosConStock ?? 0,bajo:i?.stockBajo ?? 0,sin:i?.sinStock ?? 0,vencen:i?.proximosAVencer ?? 0});Object.assign(empresa,e||{});Object.assign(dashboardVentas,d||{})}catch(e){error.value=e?.response?.data?.message||'No se pudo cargar el dashboard.'}}
onMounted(cargar)
</script>
