-row{padding:14px 2px;border-bottom:1px solid #f0f4f0;color:#607568;font-size:13px}.pay-row span{display:flex;align-items:center;gap:9px}.pay-row i{width:9px;height:9px;border-radius:50%;background:#43a047}.pay-row i.blue{background:#42a5f5}.pay-row i.orange{background:#fb8c00}.pay-row i.purple{background:#8e6bbd}.pay-row strong,.sale-total{color:#315c38}.alert-row{justify-content:flex-start;gap:13px;padding:14px 0;border-bottom:1px solid #eff4ef}.alert-row span{flex:1}.alert-row strong,.alert-row small{display:block}.alert-row .red{color:#d64b45}.alert-row .amber{color:#d38b16}.alert-row .orange{color:#dc6f1a}.sale-code{color:#315c38;font-weight:900}.empty{text-align:center;padding:28px;color:#91a095;font-size:12px}.quick-actions{display:flex;gap:12px;flex-wrap:wrap}.quick{padding:12px 18px;border:1px solid #dce9de;border-radius:12px;background:#fff;color:#4e7656;font-weight:800}.quick .q-icon{color:#3d9149;margin-right:7px}.error-banner{background:#fff5e8;color:#9a641d}@media(max-width:1000px){.kpi-grid{grid-template-columns:repeat(2,1fr)}.content-grid{grid-template-columns:1fr}}@media(max-width:600px){.dashboard-header{align-items:flex-start;flex-direction:column}.dashboard-header h1{font-size:25px}.header-actions{width:100%;justify-content:space-between}.kpi-grid{gap:10px}.kpi-card .q-card__section{padding:14px}.value{font-size:18px}.quick-actions{display:grid;grid-template-columns:1fr 1fr}.quick{padding:11px 6px}}
